import * as React from 'react'
import { Link } from 'gatsby'

import "../scss/main.scss"

import Header from "../components/Header"
import Footer from "../components/Footer"
import AccentDots from "../components/AccentDots"
import gridColours from "../data/grid-colours.json"

// ============================================
// Types
// ============================================
type GameState = 'idle' | 'showing' | 'memorising' | 'playing' | 'roundComplete' | 'gameOver'

interface Cell {
  colour: string
  order: number // sequence order (0-based)
}

interface RowMatch {
  cells: number[] // indices of cells in the match
  length: number
}

// ============================================
// Sound helper — synthesises short sounds via Web Audio API
// iOS Safari fixes: lazy AudioContext, silent buffer unlock,
// Web Audio timing (no setTimeout), setValueAtTime
// ============================================
const createSoundPlayer = () => {
  let ctx: AudioContext | null = null
  let muted = false

  const getCtx = (): AudioContext | null => {
    if (typeof window === 'undefined') return null
    try {
      if (!ctx) {
        const AC = (window as any).AudioContext || (window as any).webkitAudioContext
        if (!AC) return null
        ctx = new AC()
        const buf = ctx.createBuffer(1, 1, ctx.sampleRate)
        const src = ctx.createBufferSource()
        src.buffer = buf
        src.connect(ctx.destination)
        src.start(0)
      }
      if (ctx.state !== 'running') ctx.resume()
      return ctx
    } catch (_) {
      return null
    }
  }

  const tone = (
    ac: AudioContext,
    freq: number,
    offset: number,
    duration: number,
    type: OscillatorType = 'sine',
    volume = 0.12,
  ) => {
    const t = ac.currentTime + offset
    const osc = ac.createOscillator()
    const gain = ac.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(freq, t)
    gain.gain.setValueAtTime(volume, t)
    gain.gain.exponentialRampToValueAtTime(0.001, t + duration)
    osc.connect(gain)
    gain.connect(ac.destination)
    osc.start(t)
    osc.stop(t + duration)
  }

  // Map colour index to a pitch
  const colourPitches = [330, 392, 440, 494, 523]

  return {
    show(colourIndex: number) {
      if (muted) return
      const ac = getCtx(); if (!ac) return
      try {
        const freq = colourPitches[colourIndex % colourPitches.length]
        tone(ac, freq, 0, 0.2, 'sine', 0.1)
      } catch (_) {}
    },
    tap() {
      if (muted) return
      const ac = getCtx(); if (!ac) return
      try { tone(ac, 660, 0, 0.05, 'sine', 0.08) } catch (_) {}
    },
    correct(colourIndex: number) {
      if (muted) return
      const ac = getCtx(); if (!ac) return
      try {
        const freq = colourPitches[colourIndex % colourPitches.length]
        tone(ac, freq, 0, 0.1, 'sine', 0.1)
        tone(ac, freq * 1.25, 0.08, 0.12, 'sine', 0.08)
      } catch (_) {}
    },
    wrong() {
      if (muted) return
      const ac = getCtx(); if (!ac) return
      try {
        tone(ac, 200, 0, 0.15, 'sawtooth', 0.1)
        tone(ac, 180, 0.05, 0.15, 'sawtooth', 0.08)
      } catch (_) {}
    },
    rowMatch() {
      if (muted) return
      const ac = getCtx(); if (!ac) return
      try {
        [523, 659, 784].forEach((freq, i) => {
          tone(ac, freq, i * 0.08, 0.15, 'sine', 0.1)
        })
      } catch (_) {}
    },
    roundWin() {
      if (muted) return
      const ac = getCtx(); if (!ac) return
      try {
        [523, 659, 784, 1047].forEach((freq, i) => {
          tone(ac, freq, i * 0.1, 0.12, 'sine', 0.1)
        })
      } catch (_) {}
    },
    gameOver() {
      if (muted) return
      const ac = getCtx(); if (!ac) return
      try {
        tone(ac, 330, 0, 0.15, 'sine', 0.1)
        tone(ac, 262, 0.12, 0.25, 'sine', 0.1)
      } catch (_) {}
    },
    get muted() { return muted },
    toggleMute() { muted = !muted; return muted },
  }
}

const sound = createSoundPlayer()

// ============================================
// Game constants
// ============================================
const MOBILE_BREAKPOINT = 600 // px — matches phone breakpoint (37.5em * 16)
const INITIAL_LIVES = 3
const SHOW_DELAY = 600     // ms between each dot shown

const getGridSize = (): number => {
  if (typeof window === 'undefined') return 5
  return window.innerWidth <= MOBILE_BREAKPOINT ? 4 : 5
}

const getRoundConfig = (round: number, gridSize: number) => {
  const maxDots = gridSize === 4 ? 9 : 12
  // Slower ramp: 2 dots at round 1, then +1 every 2 rounds
  const dotCount = Math.min(1 + Math.ceil(round / 2) + 1, maxDots)
  // Longer memorise early: 4s at round 1, decreasing by 250ms per round, floor 1.5s
  const memoriseTime = Math.max(4000 - (round - 1) * 250, 1500)
  return { dotCount, memoriseTime }
}

// Pick a subset of colours for this round (4-5 colours)
const pickRoundColours = (count: number): string[] => {
  const shuffled = [...gridColours]
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]]
  }
  return shuffled.slice(0, count)
}

// Generate a sequence of N dots on random cells with colours from the subset
const generateSequence = (dotCount: number, colours: string[], gridSize: number): Map<number, Cell> => {
  const totalCells = gridSize * gridSize
  const cells = new Map<number, Cell>()
  const indices = Array.from({ length: totalCells }, (_, i) => i)

  // Shuffle and pick dotCount unique cells
  for (let i = indices.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[indices[i], indices[j]] = [indices[j], indices[i]]
  }

  const picked = indices.slice(0, dotCount)
  picked.forEach((cellIndex, order) => {
    const colour = colours[Math.floor(Math.random() * colours.length)]
    cells.set(cellIndex, { colour, order })
  })

  return cells
}

// Detect row matches (3+ same colour in a line)
const detectRowMatches = (grid: Map<number, Cell>, gridSize: number): RowMatch[] => {
  const matches: RowMatch[] = []
  const colourAt = (idx: number): string | null => grid.get(idx)?.colour || null

  // Check a line of cells for consecutive same-colour runs
  const checkLine = (indices: number[]) => {
    let i = 0
    while (i < indices.length) {
      const c = colourAt(indices[i])
      if (!c) { i++; continue }
      let j = i + 1
      while (j < indices.length && colourAt(indices[j]) === c) j++
      const len = j - i
      if (len >= 3) {
        matches.push({ cells: indices.slice(i, j), length: len })
      }
      i = j
    }
  }

  // Horizontal rows
  for (let row = 0; row < gridSize; row++) {
    const indices = Array.from({ length: gridSize }, (_, col) => row * gridSize + col)
    checkLine(indices)
  }

  // Vertical columns
  for (let col = 0; col < gridSize; col++) {
    const indices = Array.from({ length: gridSize }, (_, row) => row * gridSize + col)
    checkLine(indices)
  }

  // Diagonals (top-left to bottom-right)
  for (let start = -(gridSize - 3); start <= gridSize - 3; start++) {
    const indices: number[] = []
    for (let i = 0; i < gridSize; i++) {
      const row = i
      const col = i + start
      if (col >= 0 && col < gridSize) indices.push(row * gridSize + col)
    }
    if (indices.length >= 3) checkLine(indices)
  }

  // Diagonals (top-right to bottom-left)
  for (let start = 2; start < gridSize * 2 - 2; start++) {
    const indices: number[] = []
    for (let i = 0; i < gridSize; i++) {
      const row = i
      const col = start - i
      if (col >= 0 && col < gridSize) indices.push(row * gridSize + col)
    }
    if (indices.length >= 3) checkLine(indices)
  }

  return matches
}

// ============================================
// Component
// ============================================
const CircleMemoryPage: React.FC = () => {
  const [gridSize, setGridSize] = React.useState(() => getGridSize())
  const totalCells = gridSize * gridSize
  const [gameState, setGameState] = React.useState<GameState>('idle')
  const [round, setRound] = React.useState(1)
  const [score, setScore] = React.useState(0)
  const [highScore, setHighScore] = React.useState(0)
  const [lives, setLives] = React.useState(INITIAL_LIVES)
  const [muted, setMuted] = React.useState(false)

  // Recalculate grid size on resize (only between games)
  React.useEffect(() => {
    const handleResize = () => {
      if (gameState === 'idle' || gameState === 'gameOver') {
        setGridSize(getGridSize())
      }
    }
    window.addEventListener('resize', handleResize)
    return () => window.removeEventListener('resize', handleResize)
  }, [gameState])

  // The target sequence generated by the computer
  const [targetSequence, setTargetSequence] = React.useState<Map<number, Cell>>(new Map())
  // Ordered array of cell indices (the order player must tap)
  const [sequenceOrder, setSequenceOrder] = React.useState<number[]>([])
  // How many the computer has shown so far (during 'showing' phase)
  const [showProgress, setShowProgress] = React.useState(0)
  // How many the player has correctly placed
  const [playerProgress, setPlayerProgress] = React.useState(0)
  // Cells the player has placed (index -> Cell)
  const [playerGrid, setPlayerGrid] = React.useState<Map<number, Cell>>(new Map())
  // Wrong cell flash
  const [wrongCell, setWrongCell] = React.useState<number | null>(null)
  // Matched cells for highlight
  const [matchedCells, setMatchedCells] = React.useState<Set<number>>(new Set())
  // Bonus text to show
  const [bonusText, setBonusText] = React.useState('')
  // Celebration dots
  const [showCelebration, setShowCelebration] = React.useState(false)
  // Round colours subset
  const [roundColours, setRoundColours] = React.useState<string[]>([])

  const isIOS = React.useMemo(() => {
    if (typeof navigator === 'undefined') return false
    return /iPad|iPhone|iPod/.test(navigator.userAgent) ||
      (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1)
  }, [])

  const showTimerRef = React.useRef<ReturnType<typeof setTimeout> | null>(null)
  const memoriseTimerRef = React.useRef<ReturnType<typeof setTimeout> | null>(null)

  // Cleanup timers on unmount
  React.useEffect(() => {
    return () => {
      if (showTimerRef.current) clearTimeout(showTimerRef.current)
      if (memoriseTimerRef.current) clearTimeout(memoriseTimerRef.current)
    }
  }, [])

  // Celebration dots data
  const celebrationDots = React.useMemo(() => {
    if (!showCelebration) return []
    return Array.from({ length: 30 }, (_, i) => {
      const angle = (Math.random() * 360) * (Math.PI / 180)
      const distance = 80 + Math.random() * 160
      const x = Math.cos(angle) * distance
      const y = Math.sin(angle) * distance
      const size = 4 + Math.random() * 6
      const colour = gridColours[Math.floor(Math.random() * gridColours.length)]
      const delay = Math.random() * 0.3
      return { x, y, size, colour, delay, id: i }
    })
  }, [showCelebration])

  // Start a new round
  const startRound = React.useCallback((roundNum: number) => {
    const currentGridSize = getGridSize()
    setGridSize(currentGridSize)
    const { dotCount } = getRoundConfig(roundNum, currentGridSize)
    const colours = pickRoundColours(Math.min(4 + Math.floor(roundNum / 3), 6))
    const sequence = generateSequence(dotCount, colours, currentGridSize)

    // Build ordered array from the sequence
    const ordered: { index: number; order: number }[] = []
    sequence.forEach((cell, idx) => {
      ordered.push({ index: idx, order: cell.order })
    })
    ordered.sort((a, b) => a.order - b.order)

    setRoundColours(colours)
    setTargetSequence(sequence)
    setSequenceOrder(ordered.map(o => o.index))
    setShowProgress(0)
    setPlayerProgress(0)
    setPlayerGrid(new Map())
    setWrongCell(null)
    setMatchedCells(new Set())
    setBonusText('')
    setShowCelebration(false)
    setGameState('showing')
  }, [])

  // Computer shows dots one at a time
  React.useEffect(() => {
    if (gameState !== 'showing') return

    const totalDots = sequenceOrder.length
    if (showProgress >= totalDots) {
      // All dots shown — transition to memorising
      const { memoriseTime } = getRoundConfig(round, gridSize)
      setGameState('memorising')
      memoriseTimerRef.current = setTimeout(() => {
        setGameState('playing')
      }, memoriseTime)
      return
    }

    // Show next dot
    showTimerRef.current = setTimeout(() => {
      const cellIndex = sequenceOrder[showProgress]
      const colourIndex = roundColours.indexOf(targetSequence.get(cellIndex)!.colour)
      sound.show(colourIndex >= 0 ? colourIndex : 0)
      setShowProgress(prev => prev + 1)
    }, showProgress === 0 ? 400 : SHOW_DELAY)

    return () => {
      if (showTimerRef.current) clearTimeout(showTimerRef.current)
    }
  }, [gameState, showProgress, sequenceOrder, round, targetSequence, roundColours])

  // Handle player tap
  const handleCellTap = React.useCallback((cellIndex: number) => {
    if (gameState !== 'playing') return

    sound.tap()

    // What's the next expected cell?
    const expectedIndex = sequenceOrder[playerProgress]
    const expectedCell = targetSequence.get(expectedIndex)!

    if (cellIndex === expectedIndex) {
      // Correct!
      const colourIndex = roundColours.indexOf(expectedCell.colour)
      sound.correct(colourIndex >= 0 ? colourIndex : 0)
      if (navigator.vibrate) navigator.vibrate(15)

      const newPlayerGrid = new Map(playerGrid)
      newPlayerGrid.set(cellIndex, expectedCell)
      setPlayerGrid(newPlayerGrid)
      setScore(prev => prev + 1)

      const newProgress = playerProgress + 1
      setPlayerProgress(newProgress)

      // Check if sequence complete
      if (newProgress >= sequenceOrder.length) {
        // Detect row matches
        const matches = detectRowMatches(newPlayerGrid, gridSize)
        let bonus = 0
        const allMatchedCells = new Set<number>()

        matches.forEach(match => {
          match.cells.forEach(c => allMatchedCells.add(c))
          if (match.length >= 4) {
            bonus += 5
          } else {
            bonus += 3
          }
        })

        if (matches.length > 0) {
          setMatchedCells(allMatchedCells)
          sound.rowMatch()
          setBonusText(`Row bonus! +${bonus}`)
          setScore(prev => prev + bonus)
        }

        sound.roundWin()
        setShowCelebration(true)
        setGameState('roundComplete')
      }
    } else {
      // Wrong!
      sound.wrong()
      if (navigator.vibrate) navigator.vibrate([30, 50, 30])
      setWrongCell(cellIndex)
      setTimeout(() => setWrongCell(null), 500)

      const newLives = lives - 1
      setLives(newLives)

      if (newLives <= 0) {
        sound.gameOver()
        setGameState('gameOver')
        setHighScore(prev => Math.max(prev, score))
      }
    }
  }, [gameState, playerProgress, sequenceOrder, targetSequence, playerGrid, lives, score, roundColours])

  // Start game
  const startGame = () => {
    setRound(1)
    setScore(0)
    setLives(INITIAL_LIVES)
    startRound(1)
  }

  // Next round
  const nextRound = () => {
    const next = round + 1
    setRound(next)
    startRound(next)
  }

  // Restart after game over
  const restart = () => {
    setHighScore(prev => Math.max(prev, score))
    startGame()
  }

  // Build what to display in each cell
  const getCellState = (index: number) => {
    // Player has placed this cell
    if (playerGrid.has(index)) {
      return { filled: true, colour: playerGrid.get(index)!.colour }
    }

    // During showing phase — show dots up to showProgress
    if (gameState === 'showing' || gameState === 'memorising') {
      const cell = targetSequence.get(index)
      if (cell && cell.order < showProgress) {
        return { filled: true, colour: cell.colour }
      }
    }

    return { filled: false, colour: '' }
  }

  const { dotCount } = getRoundConfig(round, gridSize)

  return (
    <div className="container">
      <Header />

      <div className="circle-memory__hero">
        <Link to="/code" className="back-link">&larr; Back to Code</Link>
        <h1>Circle Memory</h1>
        <p>Memorise the sequence, tap it back</p>
        <AccentDots />
      </div>

      <div className="circle-memory__wrapper">
        <div className="circle-memory__content">
          {/* Status bar */}
          {gameState !== 'idle' && (
            <div className="circle-memory__status">
              <span className="circle-memory__status-item">
                Round <strong>{round}</strong>
              </span>
              <span className="circle-memory__status-item">
                Score <strong>{score}</strong>
              </span>
              <span className="circle-memory__status-item">
                <span className="circle-memory__lives">
                  {Array.from({ length: INITIAL_LIVES }, (_, i) => (
                    <span
                      key={i}
                      className={`circle-memory__heart${i >= lives ? ' circle-memory__heart--lost' : ''}`}
                    >
                      &#9829;
                    </span>
                  ))}
                </span>
              </span>
              {!isIOS && (
                <button
                  className="circle-memory__mute-btn"
                  onClick={() => setMuted(sound.toggleMute())}
                  aria-label={muted ? 'Unmute sounds' : 'Mute sounds'}
                >
                  {muted ? '\uD83D\uDD07' : '\uD83D\uDD0A'}
                </button>
              )}
            </div>
          )}

          {/* Game board */}
          <div className="circle-memory__board-area">
            {showCelebration && (
              <div className="circle-memory__celebration">
                {celebrationDots.map(dot => (
                  <span
                    key={dot.id}
                    className="circle-memory__confetti-dot"
                    style={{
                      '--dot-x': `${dot.x}px`,
                      '--dot-y': `${dot.y}px`,
                      '--dot-size': `${dot.size}px`,
                      '--dot-colour': dot.colour,
                      '--dot-delay': `${dot.delay}s`,
                    } as React.CSSProperties}
                  />
                ))}
              </div>
            )}

            <div className={`circle-memory__grid circle-memory__grid--${gridSize}x${gridSize}`}>
              {Array.from({ length: totalCells }, (_, index) => {
                const { filled, colour } = getCellState(index)
                const isDisabled = gameState !== 'playing'
                const isWrong = wrongCell === index
                const isMatched = matchedCells.has(index)

                return (
                  <div
                    key={index}
                    className={[
                      'circle-memory__cell',
                      filled && 'circle-memory__cell--filled',
                      isDisabled && 'circle-memory__cell--disabled',
                      isWrong && 'circle-memory__cell--wrong',
                      isMatched && 'circle-memory__cell--matched',
                    ].filter(Boolean).join(' ')}
                    style={filled ? { '--cell-colour': colour } as React.CSSProperties : undefined}
                    onClick={() => handleCellTap(index)}
                  />
                )
              })}
            </div>
          </div>

          {/* Message area */}
          <div className="circle-memory__message">
            {gameState === 'idle' && 'Watch the circles, remember the order'}
            {gameState === 'showing' && `Showing... ${showProgress}/${dotCount}`}
            {gameState === 'memorising' && 'Memorise!'}
            {gameState === 'playing' && `Your turn — ${playerProgress}/${sequenceOrder.length}`}
            {gameState === 'roundComplete' && 'Round complete!'}
            {gameState === 'gameOver' && ''}
          </div>

          {bonusText && <div className="circle-memory__bonus">{bonusText}</div>}

          {/* Controls */}
          <div className="circle-memory__controls">
            {gameState === 'idle' && (
              <button className="circle-memory__button" onClick={startGame}>
                Start Game
              </button>
            )}

            {gameState === 'roundComplete' && (
              <button className="circle-memory__button" onClick={nextRound}>
                Next Round
              </button>
            )}

            {gameState === 'gameOver' && (
              <div className="circle-memory__game-over">
                <div className="circle-memory__final-score">Score: {score}</div>
                {highScore > 0 && (
                  <div className="circle-memory__high-score">
                    Best: {Math.max(highScore, score)}
                  </div>
                )}
                <button className="circle-memory__button" onClick={restart}>
                  Play Again
                </button>
              </div>
            )}
          </div>
        </div>
      </div>

      <Footer />
    </div>
  )
}

export default CircleMemoryPage
